  o += line(sx(1.05), sy(0.9), sx(1.05), sy(-1.0), 'ink') + line(sx(0.95), sy(0.9), sx(0.95), sy(-1.0), 'ink');
  o += text(sx(1.18), sy(0.9) - 6, 'channel x = 1', 'ts', 'middle');
