  o += text(rx, 84, 'θ̈' + sub('1') + ' = 0.5τ' + sub('1') + ' + 0.289', 't', 'start');
  o += text(rx, 108, 'θ̈' + sub('2') + ' = −1.155', 't', 'start');
  o += text(rx, 140, 'τ = 0 时 λ = −0.167：', 'ts', 'start') + text(rx, 156, 'tip 压向 channel 左壁', 'ts', 'start');
